const ext = $('extract whatsapp fields').first().json;
const cust = $('get customer record').first().json;
const products = $('Get Products').all().map(i => i.json);
const policies = $('Get Policies').all().map(i => i.json);
const faqs = $('Get FAQ').all().map(i => i.json);
const history = $('Get History').all().map(i => i.json).filter(r => r.message).slice(-6);

// pick relevant knowledge from the earlier customer messages + the new one
const text = (history.filter(h => h.sender === "customer").map(h => h.message).join(" ") + " " + ext.message).toLowerCase();
const has = re => re.test(text);
const policyTopics = ["Company"];
const faqCats = [];
if (has(/deliver|ship|courier|arriv|parcel|track|dispatch|order/)) { policyTopics.push("Delivery"); faqCats.push("Delivery", "Orders"); }
if (has(/return|refund|money back|replace|exchange/)) { policyTopics.push("Returns", "Refund"); faqCats.push("Returns"); }
if (has(/warrant|guarantee/)) policyTopics.push("Warranty");
if (has(/pay|jazzcash|easypaisa|cash on|cod|bank|card|charged|installment/)) { policyTopics.push("Payment"); faqCats.push("Payment"); }
if (has(/not working|not charging|connect|pair|wifi|wi-fi|setup|set up|reset|battery|broken|dead|won't|doesn't/)) faqCats.push("Technical");

const lines = [];
const named = products.filter(p => text.includes(String(p.name).toLowerCase().split(" ")[0]));
if (named.length) {
  named.forEach(p => lines.push(`PRODUCT: ${p.name} | ${p.description} | Specs: ${p.specs} | Price: PKR ${p.price_pkr} | Warranty: ${p.warranty} | Stock: ${p.stock_status}`));
} else {
  products.forEach(p => lines.push(`PRODUCT: ${p.name} | PKR ${p.price_pkr}`));
}
policies.filter(p => policyTopics.includes(p.topic)).forEach(p => lines.push(`POLICY (${p.topic}) ${p.title}: ${p.content}`));
faqs.filter(f => faqCats.includes(f.category)).forEach(f => lines.push(`FAQ: ${f.question} -> ${f.answer}`));
const knowledge = lines.join("\n");

const SYSTEM_PROMPT = `You are the virtual support assistant for SwiftCart Electronics, an online gadget store in Pakistan. You chat with customers on WhatsApp.

TONE
- Warm, polite and calm. Professional but friendly, like a helpful support agent.
- Short WhatsApp style: at most 3 short sentences, simple words, no jargon, no long lists.
- Use the customer's first name only in the first message of a conversation. Do not greet again later.
- If the customer is upset, apologise once, briefly, then help.
- Follow the LANGUAGE FOR THIS REPLY line below. When it says Roman Urdu, write the whole reply in Roman Urdu (Urdu in English letters), for example "Meherbani karke apna order number bata dein."
- If asked, say you are SwiftCart's virtual assistant.

FACTS
- Use ONLY the KNOWLEDGE BASE below for facts. Never invent prices, dates, stock, specifications, discounts, policies or order status.
- You cannot see or check individual orders, and you cannot approve refunds, replacements or exceptions. The support team does that. Never say that you will check an order yourself. Say the support team will check it.
- If the answer is not in the knowledge base, say you do not have that information and a team member will help. Set needs_human to true.
- Do not promise how fast the team will reply. Never use the words "soon" or "shortly".
- Never say or imply that a refund, replacement or return will be given. Say the support team will review the request.
- Answer the question first, in plain words. Do not add sales lines such as "let me know if you want to buy".

CONVERSATION
- Read the earlier messages. Use them to understand follow-ups such as "it", "that one" or "what about the price?".
- Never ask for information the customer already gave in this conversation or that is in the customer details. Check before you ask.
- If information is missing, ask for it, ONE question at a time. Needed information:
  * order status or delivery problem: order number
  * return, refund or warranty claim: order number, product, and what is wrong
  * technical problem: product name and what happens
  * payment problem such as a double charge: order number and a screenshot of the payment
- When you have everything and the request needs the support team (order check, return, refund, warranty claim, payment problem, complaint), repeat the key details in one sentence, say the support team will take it from here, and set needs_human to true.
- THE ESCALATION RULES BELOW OVERRIDE ALL OTHER RULES ABOVE. For human_requested, complaint and sensitive_account, never ask for missing information first: escalate in this same reply. For refund_dispute, the only information needed before escalating is the order number, which may already be in the customer message; do not ask for a payment screenshot or other details, the support team will ask. Detect these cases in Roman Urdu too (for example: naraz, bohat kharab service, bakwas, insaan se baat karni hai).
- Set escalation_reason and needs_human to true in these cases:
  * human_requested: the customer asks for a human, agent, manager or representative. Escalate immediately.
  * complaint: the customer is angry, abusive, or still unhappy after your help. Escalate immediately.
  * sensitive_account: the customer mentions a password, card number, hacked account or personal data. Escalate immediately. Never ask the customer to share a password or card number.
  * refund_dispute: the customer disputes a refund, or was charged twice. Ask for the order number first. Once you have it, escalate.
  * unclear_question: you already asked ONE clarifying question and still cannot understand the customer.
  * repeated_failure: you already could not answer this customer earlier in this conversation and still cannot.
  Asking for an order number is normal missing information and is NOT unclear_question. Otherwise escalation_reason is "none".
- When you escalate, say in one short sentence that a team member will help. Do not try to solve the problem yourself.
- Set answer_failed to true only if the answer is not in the knowledge base.
- Answer questions directly from the knowledge base when you can. Do not ask for details you do not need.
- conversation_status: "resolved" when you fully answered the question, "waiting_for_customer" when you asked the customer something, "escalated" when needs_human is true, "open" otherwise.

OUTPUT
Return ONLY a JSON object, with no other text, even if earlier assistant messages were plain text:
{"reply":"message for the customer","intent":"one short sentence","category":"Product Information | Pricing | Order Status | Delivery | Payment | Return | Refund | Warranty | Complaint | Technical Support | Human Assistance | General Inquiry","urgency":"low | medium | high","collected_info":{"order_id":null,"product":null,"issue":null},"missing_info":[],"needs_human":false,"escalation_reason":"none | human_requested | complaint | sensitive_account | refund_dispute | unclear_question | repeated_failure","answer_failed":false,"conversation_status":"open | waiting_for_customer | resolved | escalated"}`;

const firstName = String(ext.customer_name || "").split(" ")[0];

// decide the reply language in code, not only in the prompt
const urduWords = /\b(mera|meri|mujhe|nahi|nahin|kya|kahan|kab|kitni|kitna|aya|aaya|ho gaye|bata|batao|chahiye|karna|karo|aap|apna|din)\b/i;
const lastCustomer = history.filter(h => h.sender === "customer").slice(-1).map(h => h.message).join(" ");
const languageNote = urduWords.test(lastCustomer + " " + ext.message) ? "\nLANGUAGE FOR THIS REPLY: Roman Urdu. Write the whole reply in Roman Urdu (Urdu in English letters)." : "\nLANGUAGE FOR THIS REPLY: English.";

const context = `\n\nCUSTOMER DETAILS: first name: ${firstName}; phone: ${ext.phone_number}\nEARLIER MESSAGES IN THIS CONVERSATION: ${history.length}${languageNote}\n\nKNOWLEDGE BASE:\n${knowledge}`;
const chat = history.map(h => ({ role: h.sender === "bot" ? "assistant" : "user", content: String(h.message).slice(0, 300) }));

return [{ json: {
  customer_id: cust.customer_id, conversation_id: cust.conversation_id,
  customer_name: ext.customer_name, phone_number: ext.phone_number, message: ext.message,
  history_count: history.length, knowledge,
  body: {
    model: "openai/gpt-oss-20b",
    temperature: 0.2,
    response_format: { type: "json_object" },
    messages: [ { role: "system", content: SYSTEM_PROMPT + context }, ...chat, { role: "user", content: ext.message } ]
  }
} }];

const req = $('Build Agent Request').first().json;
const reasons = ['complaint','refund_dispute','sensitive_account','unclear_question','repeated_failure','human_requested','none'];
const fallback = { reply: "Thank you for your message. A team member will help you with this.", intent: "AI answer could not be read", category: "Human Assistance", urgency: "medium", collected_info: {}, missing_info: [], needs_human: true, escalation_reason: "system_error", answer_failed: true, conversation_status: "escalated", parse_error: true };
let ai;
try {
  const text = ($json.choices?.[0]?.message?.content || "").replace(/```json|```/g, "").trim();
  ai = JSON.parse(text);
  if (typeof ai.reply !== "string" || !ai.reply.trim()) ai = fallback;
} catch (e) { ai = fallback; }
let reason = (reasons.includes(ai.escalation_reason) || ai.escalation_reason === "system_error") ? ai.escalation_reason : "none";
const needsHuman = ai.needs_human === true || reason !== "none";
if (needsHuman && reason === "none") reason = "other";
return { json: {
  customer_id: req.customer_id, conversation_id: req.conversation_id, customer_name: req.customer_name,
  phone_number: req.phone_number, message: req.message,
  reply_text: ai.reply, intent: ai.intent, category: ai.category, urgency: ai.urgency,
  collected_info: ai.collected_info, missing_info: ai.missing_info,
  needs_human: needsHuman, escalation_reason: reason, answer_failed: ai.answer_failed === true,
  conversation_status: needsHuman ? "escalated" : (ai.conversation_status || "open"),
  parse_error: ai.parse_error === true
} };

const r = $input.first().json;
const ts = $now.toFormat("yyyy-MM-dd HH:mm");
return [
  { json: { conversation_id: r.conversation_id, customer_id: r.customer_id, message: r.message, sender: "customer", timestamp: ts, intent: r.category, resolution_status: r.conversation_status } },
  { json: { conversation_id: r.conversation_id, customer_id: r.customer_id, message: r.reply_text, sender: "bot", timestamp: ts, intent: r.category, resolution_status: r.conversation_status } }
];

const r = $('Read Agent Reply').first().json;
const tickets = $('Get Tickets').all().map(i => i.json).filter(t => t.ticket_id);

const mine = tickets.filter(t => t.customer_id === r.customer_id && ["Open", "In Progress", "Human Review"].includes(t.status));
const existing = mine[mine.length - 1];
const hasOpen = mine.length > 0;
const nums = tickets.map(t => parseInt(String(t.ticket_id).replace("TCK-", ""), 10)).filter(n => !isNaN(n));
const next = (nums.length ? Math.max(...nums) : 0) + 1;
const ticketId = "TCK-" + String(next).padStart(4, "0");

return [{ json: { ...r,
  create_ticket: r.needs_human === true && !hasOpen,
  has_open_ticket: hasOpen,
  ticket_id: ticketId,
  existing_ticket_id: existing ? existing.ticket_id : "",
  update_existing: r.needs_human === true && !!existing && existing.status !== "Human Review"
} }];

const d = $input.first().json;
const hist = $('Get History').all().map(i => i.json).filter(h => h.message).slice(-6);
const convo = hist.map(h => `${h.sender === "bot" ? "Agent" : "Customer"}: ${String(h.message).slice(0, 300)}`).join("\n")
  + `\nCustomer: ${d.message}\nAgent: ${d.reply_text}\nEscalation reason: ${d.escalation_reason}`;

const SYSTEM = `You create support tickets for SwiftCart Electronics, an online gadget store in Pakistan. You read a chat between a customer and the virtual agent, and you write a ticket for the human support team.

Return ONLY a JSON object:
{"issue":"...","summary":"...","priority":"General Inquiry | Normal | Important | Urgent","category":"...","reason":"..."}

Rules:
- issue: the customer's problem in one short sentence (maximum 20 words). Use facts from the chat only.
- summary: 2 to 3 short sentences for the support agent: what happened, what the customer already gave (order number, product), and what is still needed. Do not invent facts. Write in English even if the customer used Roman Urdu.
- category: one of Product Information, Pricing, Order Status, Delivery, Payment, Return, Refund, Warranty, Complaint, Technical Support, Human Assistance, General Inquiry.
- priority:
  * Urgent: the customer lost money (double charge, wrong amount), made a legal threat, reports a safety danger (overheating, fire, injury), or is very angry after repeated failures.
  * Important: faulty or damaged product, return, refund or warranty claim, an order later than the normal delivery time (3 to 5 working days, up to 7 for remote areas), or the customer asks for a manager.
  * Normal: a routine order status or delivery check, or a minor product problem.
  * General Inquiry: a question the knowledge base could not answer, with no problem to fix (for example a product detail or a store location).
- The last line of the chat is "Escalation reason", the reason the agent handed over. human_requested: priority at least Normal. complaint or refund_dispute: priority at least Important. sensitive_account: Urgent. Mention the escalation reason in the summary.
- reason: one short sentence explaining why you chose this priority.`;

return [{ json: { ...d, body: {
  model: "openai/gpt-oss-20b",
  temperature: 0,
  response_format: { type: "json_object" },
  messages: [ { role: "system", content: SYSTEM }, { role: "user", content: convo } ]
} } }];

const dec = $('Ticket Decision').first().json;
const d = $('Ticket AI Request').first().json;
const fallback = {
  issue: d.message,
  summary: "Customer needs help. The AI summary could not be created. Last customer message: " + d.message,
  priority: "Normal", category: d.category || "Human Assistance",
  reason: "AI summary unavailable, default priority used"
};
let t;
try {
  const text = ($json.choices?.[0]?.message?.content || "").replace(/```json|```/g, "").trim();
  t = JSON.parse(text);
  if (!t.summary || !t.priority) t = fallback;
} catch (e) { t = fallback; }

const PRIORITIES = ["General Inquiry", "Normal", "Important", "Urgent"];
if (!PRIORITIES.includes(t.priority)) t.priority = "Normal";

// Step 8: simulated assignment (fictional team)
const TEAM = {
  "Return": "Ayesha Khan (Returns and Warranty)", "Refund": "Ayesha Khan (Returns and Warranty)", "Warranty": "Ayesha Khan (Returns and Warranty)",
  "Order Status": "Bilal Ahmed (Orders and Delivery)", "Delivery": "Bilal Ahmed (Orders and Delivery)",
  "Payment": "Sana Malik (Payments)", "Technical Support": "Usman Tariq (Technical Support)"
};
const ROTATION = ["Bilal Ahmed (Orders and Delivery)", "Usman Tariq (Technical Support)", "Sana Malik (Payments)"];
const n = parseInt(String(d.ticket_id).replace("TCK-", ""), 10) || 0;
let assignedTo = TEAM[t.category] || ROTATION[n % ROTATION.length];
if (t.priority === "Urgent") assignedTo = "Hira Noor (Escalations Lead)";

return { json: {
  ticket_id: d.ticket_id, customer_id: d.customer_id, conversation_id: d.conversation_id,
  category: t.category, issue: t.issue, summary: t.summary,
  priority: t.priority, priority_reason: t.reason,
  status: "Human Review", escalation_reason: dec.escalation_reason || "", assigned_to: assignedTo,
  created_date: $now.toFormat("yyyy-MM-dd HH:mm"), resolved_date: "", resolution: ""
} };

