const cust = $('get customer record').first().json;
const tickets = $('Get Tickets Early').all().map(i => i.json).filter(t => t.ticket_id);
const handoff = tickets.some(t => t.customer_id === cust.customer_id && t.status === 'Human Review');
return [{ json: { ...cust, handoff } }];
